  t("Filtrar por texto (sin distinguir tildes) y por rango de fechas; se combinan; «Limpiar filtros» los quita", () => { fill("#fWho", ""); fill("#fQ", "sabado"); assert.equal(rowsN(), 1); assert.match(firstRow(), /Cena del sábado/); fill("#fQ", ""); fill("#fFrom", "2026-10-31"); fill("#fTo", "2026-10-31"); assert.equal(rowsN(), 1); fill("#fWho", "ana"); assert.match($("#expArea").textContent, /Ningún gasto coincide con los filtros/); click('#expArea [data-act="clear-filters"]'); assert.equal(rowsN(), 5); assert.equal($("#fQ").value, ""); });
  t("Ordenar por monto: mayor primero (Alquiler de la casa) y menor primero (Entradas al parque ₡27 000,25)", () => { fill("#fSort", "amt-desc"); assert.match(firstRow(), /Alquiler de la casa/); fill("#fSort", "amt-asc"); assert.match(firstRow(), /Entradas al parque/); fill("#fSort", "date-desc"); });
