  t("«Ver sus gastos» lleva a Gastos ya filtrado por esa persona (el «Detalles» del SaldApp original)", () => { assert.match(w.location.hash, /#\/g\/g1\/gastos/); assert.equal($("#fWho").value, "carla"); assert.equal(rowsN(), 1); assert.match(firstRow(), /Cena del sábado/); click('[data-act="clear-filters"]'); });
  // ── Resumen por participante (el «Detalles» del prototipo original) ──
  await go("#/g/g1/resumen");
  t("Resumen: cada participante es un acordeón con total pagado, parte asignada y saldo en palabras; su detalle muestra SOLO sus gastos", () => { assert.equal($$("details.acc").length, 5); const b = $('details.acc[data-who="beto"]'), sum = nz(b.querySelector("summary")); assert.match(sum, /Beto/); assert.match(sum, /Total pagado ?₡45 230,50/); assert.match(sum, /Parte asignada ?₡70 596,15/); assert.match(sum, /Debe/); assert.match(nz(b.querySelector(".accbody")), /Gastos pagados por Beto/); assert.match(nz(b.querySelector(".accbody")), /Supermercado/); assert.doesNotMatch(nz(b.querySelector(".accbody")), /Alquiler de la casa/); });
  t("Resumen: Ana puede editar o eliminar desde el detalle de cualquier persona; vista previa de la liquidación (3 pagos y «y 1 más») con enlaces", () => { assert.equal($$('details.acc [data-act="edit-exp"]').length, 5); assert.match(main(), /Liquidación sugerida/); assert.equal($$(".resgrid .pay").length, 3); assert.match(main(), /y 1 más/); assert.ok($('a[href="#/g/g1/liquidar"]') && $('a[href="#/g/g1/saldos"]') && $('a[href="#/g/g1/gastos"]')); });
  await go("#/g/g1/gastos");
  t("Las pestañas del grupo se recorren con las flechas (y Inicio/Fin), como en el prototipo original", () => { const l = [...$$(".tabsd a")]; l[0].focus(); l[0].dispatchEvent(new w.KeyboardEvent("keydown", { key: "ArrowRight", bubbles: true, cancelable: true })); assert.equal(d.activeElement, l[1]); l[1].dispatchEvent(new w.KeyboardEvent("keydown", { key: "End", bubbles: true, cancelable: true })); assert.equal(d.activeElement, l[l.length - 1]); l[l.length - 1].dispatchEvent(new w.KeyboardEvent("keydown", { key: "ArrowRight", bubbles: true, cancelable: true })); assert.equal(d.activeElement, l[0]); });
  t("Gastos: «Pagados por mí» y «por otras personas», y orden alfabético A–Z / Z–A (además de fecha y monto)", () => { fill("#fWho", "me"); assert.equal(rowsN(), 2); fill("#fWho", "others"); assert.equal(rowsN(), 3); fill("#fWho", ""); fill("#fSort", "alpha-asc"); assert.match(firstRow(), /Alquiler de la casa/); fill("#fSort", "alpha-desc"); assert.match(firstRow(), /Supermercado/); fill("#fSort", "date-desc"); });
  // ── Gestión de gastos (administración): hoja con borrador y guardado atómico ──
  await go("#/g/g1/gestion");
  const gt = () => $$("#gtable tbody tr"), gcell = (desc, f) => [...gt()].find((tr) => tr.querySelector('[data-gf="description"]').value === desc).querySelector(`[data-gf="${f}"]`);
  const gedit = (el, v) => { el.value = v; el.dispatchEvent(new w.Event("input", { bubbles: true })); el.dispatchEvent(new w.Event("change", { bubbles: true })); };
  const key = (el, k) => el.dispatchEvent(new w.KeyboardEvent("keydown", { key: k, bubbles: true, cancelable: true }));
  t("Gestión de gastos: una fila por gasto (fecha reciente primero), total de la tabla, «Sin cambios pendientes» y Guardar deshabilitado", () => { assert.equal(gt().length, 5); assert.equal(gt()[0].querySelector('[data-gf="description"]').value, "Entradas al parque"); assert.match(nz($("#gTot")), /₡352 980,75/); assert.ok(!$("#gClean").hidden); assert.ok($("#gDirty").hidden); assert.ok($$(".gsave").every((b) => b.disabled)); assert.match(nz($("#gCounts")), /0 nuevas · 5 guardadas/); });
  t("Editar celdas NO toca los saldos hasta guardar: aparece «Hay cambios sin guardar», cambia el total de la tabla y el resumen del grupo sigue igual", () => { gedit(gcell("Supermercado", "amount"), "50000,00"); assert.ok(!$("#gDirty").hidden); assert.match(nz($("#gDirty")), /Hay cambios sin guardar/); assert.match(nz($("#gTot")), /₡357 750,25/); assert.match(nz($(".hero")), /Total del grupo ?₡352 980,75/); assert.ok($$(".gsave").every((b) => !b.disabled)); });
  t("Guardar valida TODAS las filas: con un monto inválido no se guarda nada, marca la celda con su mensaje y los saldos siguen igual", () => { gedit(gcell("Supermercado", "amount"), "12,505"); click('[data-act="g-save"]'); assert.ok(!$("#gVal").hidden); assert.match(nz($("#gVal")), /La tabla no se guardará hasta corregirlos/); assert.match(nz($("#gtable")), /admite hasta 2 decimales/); assert.ok($('#gtable [data-gf="amount"][aria-invalid="true"]')); assert.match(nz($(".hero")), /Total del grupo ?₡352 980,75/); });
  t("Corregir el monto limpia los avisos y Guardar aplica todo junto: saldos recalculados y «Deshacer» el guardado", () => { gedit(gcell("Supermercado", "amount"), "50000,00"); assert.ok($("#gVal").hidden); assert.ok(!$('#gtable [aria-invalid="true"]')); click('[data-act="g-save"]'); assert.match(nz($(".hero")), /Total del grupo ?₡357 750,25/); assert.match($("#toast").textContent, /Cambios guardados/); assert.ok($('[data-act="toast-undo"]')); click('[data-act="toast-undo"]'); assert.match(nz($(".hero")), /Total del grupo ?₡352 980,75/); assert.equal(gcell("Supermercado", "amount").value, "45230,50"); });
  t("Agregar fila: aparece arriba con la fecha de hoy y quien paga por defecto, con el foco en la descripción; incompleta no se guarda", () => { click('[data-act="g-add"]'); assert.equal(gt().length, 6); const f = gt()[0]; assert.ok(f.classList.contains("newrow")); assert.equal(d.activeElement, f.querySelector('[data-gf="description"]')); assert.match(nz($("#gCounts")), /1 nuevas/); click('[data-act="g-save"]'); assert.match(nz($("#gtable")), /Debe tener entre 4 y 500 caracteres/); assert.match(nz($("#gtable")), /Escriba el monto/); });
