  t("Quitar filas (papelera o selección múltiple) NO aplica nada: los saldos no cambian; «Descartar» recupera todo", () => { const pick = (desc) => { const c = gcell(desc, "description").closest("tr").querySelector("[data-gsel]"); c.checked = true; c.dispatchEvent(new w.Event("change", { bubbles: true })); }; pick("Hielo"); pick("Cena del sábado"); assert.match(nz($("#gRmSel")), /Quitar seleccionadas \(2\)/); click("#gRmSel"); assert.equal(gt().length, 4); assert.match(nz($(".hero")), /Total del grupo ?₡356 480,75/); assert.ok(!$("#gDirty").hidden); click('[data-act="g-discard"]'); click("#dlg [data-x=ok]"); assert.equal(gt().length, 6); assert.ok($("#gDirty").hidden); });
  t("«Deshacer» tras quitar una fila la devuelve a su lugar; quitar «Hielo» y guardar deja el total como al inicio", () => { click(`[data-act="g-rm"][data-k="${gcell("Hielo", "description").closest("tr").dataset.key}"]`); assert.equal(gt().length, 5); click('[data-act="toast-undo"]'); assert.equal(gt().length, 6); assert.ok(gcell("Hielo", "description")); click(`[data-act="g-rm"][data-k="${gcell("Hielo", "description").closest("tr").dataset.key}"]`); click('[data-act="g-save"]'); assert.match(nz($(".hero")), /Total del grupo ?₡352 980,75/); assert.equal(gt().length, 5); });
  const pasteG = (text) => { const ev = new w.Event("paste", { bubbles: true, cancelable: true }); ev.clipboardData = { getData: () => text }; $('#gtable [data-gf="description"]').dispatchEvent(ev); };
